syntax:
const int MAX = 100;      // biggest size we allow
int a[MAX];               // MAX boxes, indexes 0 .. MAX-1
int n;                    // how many boxes we really use
cin >> n;                 // read the size first (n must be <= MAX)

for (int i = 0; i < n; i++) {   // fill: i = 0, 1, ... n-1
    cin >> a[i];                // read into box i
}

for (int i = 0; i < n; i++) {   // show in order
    cout << a[i] << " ";
}

for (int i = n - 1; i >= 0; i--) {  // show in reverse
    cout << a[i] << " ";
}

sample.code:
#include <iostream>
using namespace std;

int main() {
    int a[3];
    for (int i = 0; i < 3; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < 3; i++) {
        cout << "a[" << i << "] = " << a[i] << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    const int MAX = 100;
    int a[MAX];
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    cout << "Reverse: ";
    for (int i = n - 1; i >= 0; i--) {
        cout << a[i] << " ";
    }
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    const int MAX = 10;
    int marks[MAX];
    int n;
    cin >> n;
    if (n < 1 || n > MAX) {
        cout << "Invalid size" << endl;
        return 0;
    }
    for (int i = 0; i < n; i++) {
        cin >> marks[i];
    }
    for (int i = 0; i < n; i++) {
        cout << "Student " << i + 1 << ": " << marks[i] << endl;
    }
    cout << "First = " << marks[0] << ", Last = " << marks[n - 1] << endl;
    return 0;
}

